export function encode(v) {
  const out = new Out();
  writeRequest(out, v, 0);
  out.byte(0x0a);
  return out.bytes();
}

// A BOM inside a JSON string is data, not a stream signature.
const DEC = new TextDecoder("utf-8", {ignoreBOM: true});
const DEPTH_LIMIT = 64;
const I64_DIGITS = 19;
const UNESCAPE = { 0x22: 0x22, 0x5c: 0x5c, 0x2f: 0x2f, 0x62: 0x08, 0x66: 0x0c, 0x6e: 0x0a, 0x72: 0x0d, 0x74: 0x09 };

export class Refusal extends Error {
  constructor(word, offset) {
    super("refused: " + word + " at byte " + offset);
    this.name = "Refusal";
    this.word = word;
    this.offset = offset;
  }
}

function appendRune(out, cp) {
  if (cp < 0x80) out.push(cp);
  else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
  else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
}

// TextDecoder substitutes U+FFFD for a bad sequence rather than reporting it, so
// the bytes are checked before they are decoded and the refusal says so.
function validUtf8(b) {
  for (let i = 0; i < b.length; ) {
    const c = b[i];
    if (c < 0x80) { i++; continue; }
    let n, cp;
    if (c >> 5 === 0x6) { n = 2; cp = c & 0x1f; }
    else if (c >> 4 === 0xe) { n = 3; cp = c & 0x0f; }
    else if (c >> 3 === 0x1e) { n = 4; cp = c & 0x07; }
    else return false;
    if (i + n > b.length) return false;
    for (let k = 1; k < n; k++) {
      if (b[i + k] >> 6 !== 0x2) return false;
      cp = (cp << 6) | (b[i + k] & 0x3f);
    }
    const lowest = [0, 0, 0x80, 0x800, 0x10000][n];
    if (cp < lowest || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return false;
    i += n;
  }
  return true;
}

class Reader {
  constructor(buf) { this.buf = buf; this.pos = 0; this.depth = 0; }

  refuse(word) { return new Refusal(word, this.pos); }

  at() { return this.pos < this.buf.length ? this.buf[this.pos] : 0; }

  digit() { const c = this.at(); return c >= 0x30 && c <= 0x39; }

  ws() { while (this.pos < this.buf.length && isWs(this.buf[this.pos])) this.pos++; }

  enter() {
    this.depth++;
    if (this.depth > DEPTH_LIMIT) throw this.refuse("depth_exceeded");
  }

  string() {
    if (this.at() !== 0x22) throw this.refuse("wrong_type");
    this.pos++;
    const out = [];
    for (;;) {
      if (this.pos >= this.buf.length) throw this.refuse("malformed");
      const c = this.buf[this.pos];
      if (c === 0x22) {
        this.pos++;
        const bytes = Uint8Array.from(out);
        if (!validUtf8(bytes)) throw this.refuse("bad_string");
        return DEC.decode(bytes);
      }
      if (c < 0x20) throw this.refuse("bad_string");
      if (c === 0x5c) this.escape(out);
      else { out.push(c); this.pos++; }
    }
  }

  escape(out) {
    this.pos++;
    if (this.pos >= this.buf.length) throw this.refuse("malformed");
    const c = this.buf[this.pos];
    this.pos++;
    const plain = UNESCAPE[c];
    if (plain !== undefined) { out.push(plain); return; }
    if (c !== 0x75) throw this.refuse("bad_string");
    let u = this.hex4();
    if (u >= 0xdc00 && u <= 0xdfff) throw this.refuse("bad_string");
    if (u >= 0xd800 && u <= 0xdbff) {
      if (this.pos + 1 >= this.buf.length || this.buf[this.pos] !== 0x5c || this.buf[this.pos + 1] !== 0x75)
        throw this.refuse("bad_string");
      this.pos += 2;
      const low = this.hex4();
      if (low < 0xdc00 || low > 0xdfff) throw this.refuse("bad_string");
      u = 0x10000 + ((u - 0xd800) << 10) + (low - 0xdc00);
    }
    appendRune(out, u);
  }

  hex4() {
    if (this.pos + 4 > this.buf.length) throw this.refuse("bad_string");
    let u = 0;
    for (let i = 0; i < 4; i++) {
      const c = this.buf[this.pos + i];
      if (c >= 0x30 && c <= 0x39) u = (u << 4) | (c - 0x30);
      else if (c >= 0x61 && c <= 0x66) u = (u << 4) | (c - 0x61 + 10);
      else if (c >= 0x41 && c <= 0x46) u = (u << 4) | (c - 0x41 + 10);
      else throw this.refuse("bad_string");
    }
    this.pos += 4;
    return u;
  }

  integer(low, high) {
    const c = this.at();
    if (c !== 0x2d && (c < 0x30 || c > 0x39)) throw this.refuse("wrong_type");
    const negative = c === 0x2d;
    if (negative) this.pos++;
    if (!this.digit()) throw this.refuse("malformed");
    const start = this.pos;
    if (this.at() === 0x30) this.pos++;
    else while (this.digit()) this.pos++;
    const after = this.at();
    if (after === 0x2e || after === 0x65 || after === 0x45 || this.digit()) throw this.refuse("number_spelling");
    if (this.pos - start > I64_DIGITS) throw this.refuse("number_spelling");
    let n = BigInt(String.fromCharCode(...this.buf.subarray(start, this.pos)));
    if (negative) {
      if (n === 0n) throw this.refuse("number_spelling");
      n = -n;
    }
    if (n < low || n > high) throw this.refuse("number_spelling");
    return n;
  }

  boolean() {
    if (this.at() === 0x74) { this.literal("true"); return true; }
    if (this.at() === 0x66) { this.literal("false"); return false; }
    throw this.refuse("wrong_type");
  }

  literal(word) {
    for (let i = 0; i < word.length; i++)
      if (this.buf[this.pos + i] !== word.charCodeAt(i)) throw this.refuse("malformed");
    this.pos += word.length;
  }

  strList() {
    if (this.at() !== 0x5b) throw this.refuse("wrong_type");
    this.enter();
    this.pos++;
    const out = [];
    this.ws();
    if (this.at() !== 0x5d) {
      for (;;) {
        this.ws();
        out.push(this.string());
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== 0x5d) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
    return out;
  }

  rawMap() {
    if (this.at() !== 0x7b) throw this.refuse("wrong_type");
    this.enter();
    this.pos++;
    const out = Object.create(null);
    this.ws();
    if (this.at() !== 0x7d) {
      for (;;) {
        this.ws();
        if (this.at() !== 0x22) throw this.refuse("malformed");
        const k = this.string();
        if (k in out) throw this.refuse("duplicate_key");
        this.ws();
        if (this.at() !== 0x3a) throw this.refuse("malformed");
        this.pos++;
        this.ws();
        out[k] = this.rawValue();
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== 0x7d) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
    return out;
  }

  rawValue() {
    const start = this.pos;
    this.skipValue();
    return this.buf.subarray(start, this.pos);
  }

  skipValue() {
    const c = this.at();
    if (c === 0x22) this.skipString();
    else if (c === 0x7b || c === 0x5b) this.skipContainer();
    else if (c === 0x74) this.literal("true");
    else if (c === 0x66) this.literal("false");
    else if (c === 0x6e) this.literal("null");
    else if (c === 0x2d || (c >= 0x30 && c <= 0x39)) this.skipNumber();
    else throw this.refuse("malformed");
  }

  // An opaque value is validated and carried, never interpreted. Its syntax is
  // the record's own — the same string reader, so an escape, a control byte or a
  // lone surrogate is judged identically at any depth — and what it is free to
  // spell, it keeps: the bytes between these two offsets are what a writer
  // re-emits. A number is walked, never converted, so a value no host type holds
  // survives the reader that carried it.
  skipString() {
    this.string();
  }

  someDigits() {
    let n = 0;
    while (this.at() >= 0x30 && this.at() <= 0x39) { this.pos++; n++; }
    if (n === 0) throw this.refuse("number_spelling");
  }

  skipNumber() {
    if (this.at() === 0x2d) this.pos++;
    const c = this.at();
    if (c === 0x30) this.pos++;
    else if (c > 0x30 && c <= 0x39) { while (this.at() >= 0x30 && this.at() <= 0x39) this.pos++; }
    else throw this.refuse("number_spelling");
    if (this.at() === 0x2e) { this.pos++; this.someDigits(); }
    if (this.at() === 0x65 || this.at() === 0x45) {
      this.pos++;
      if (this.at() === 0x2b || this.at() === 0x2d) this.pos++;
      this.someDigits();
    }
  }

  skipContainer() {
    const opener = this.at();
    const shut = opener === 0x7b ? 0x7d : 0x5d;
    this.enter();
    this.pos++;
    this.ws();
    const seen = new Set();
    if (this.at() !== shut) {
      for (;;) {
        this.ws();
        if (opener === 0x7b) {
          if (this.at() !== 0x22) throw this.refuse("malformed");
          const k = this.string();
          if (seen.has(k)) throw this.refuse("duplicate_key");
          seen.add(k);
          this.ws();
          if (this.at() !== 0x3a) throw this.refuse("malformed");
          this.pos++;
          this.ws();
        }
        this.skipValue();
        this.ws();
        if (this.at() !== 0x2c) break;
        this.pos++;
      }
    }
    if (this.at() !== shut) throw this.refuse("malformed");
    this.pos++;
    this.depth--;
  }
}

function strMap(r) {
  if (r.at() !== 0x7b) throw r.refuse("wrong_type");
  r.enter();
  r.pos++;
  const out = Object.create(null);
  r.ws();
  if (r.at() !== 0x7d) {
    for (;;) {
      r.ws();
      if (r.at() !== 0x22) throw r.refuse("malformed");
      const k = r.string();
      if (k in out) throw r.refuse("duplicate_key");
      r.ws();
      if (r.at() !== 0x3a) throw r.refuse("malformed");
      r.pos++;
      r.ws();
      out[k] = r.string();
      r.ws();
      if (r.at() !== 0x2c) break;
      r.pos++;
    }
  }
  if (r.at() !== 0x7d) throw r.refuse("malformed");
  r.pos++;
  r.depth--;
  return out;
}

function readList(r, elem) {
  if (r.at() !== 0x5b) throw r.refuse("wrong_type");
  r.enter();
  r.pos++;
  const out = [];
  r.ws();
  if (r.at() !== 0x5d) {
    for (;;) {
      r.ws();
      out.push(elem(r));
      r.ws();
      if (r.at() !== 0x2c) break;
      r.pos++;
    }
  }
  if (r.at() !== 0x5d) throw r.refuse("malformed");
  r.pos++;
  r.depth--;
  return out;
}

// One piece of a message. text: text. image: only in a user message; digest is
// a canonical lowercase sha256 digest, media_type is one of image/png,
// image/jpeg, image/gif or image/webp, and the bytes are resolved under the
// original caller's rights and verified before upstream. No image bytes travel
// in a request. tool_call: call_id, name and arguments, a JSON text.
// tool_result: call_id and text. Fields a kind does not name are empty. In a
// delta, a part extends the reply part at its index: text and arguments append,
// and call_id, name, digest and media_type are set by the first delta of that
// index.
export function newPart() {
  return { kind: "", text: "", digest: "", mediaType: "", callId: "", name: "", arguments: "" };
}

// parts is 1..64 parts in a request. A reply message has role assistant.
export function newMessage() {
  return { role: "", parts: [] };
}

// A function the model may call. name is 1..64 bytes of A-Z a-z 0-9 _ -;
// parameters is a JSON Schema object as JSON text.
export function newTool() {
  return { name: "", description: "", parameters: "" };
}

// Sampling temperature in thousandths, 0..2000.
export function newTemperature() {
  return { milli: 0n };
}

// max_output bounds output tokens (0 is the host's default). temperature, when
// absent, is the host's default. stop is 0..8 sequences. json_schema is a JSON
// Schema object as JSON text the reply must satisfy; a host without
// abstraction.inference/json-schema@1 refuses it.
export function newOptions() {
  return { maxOutput: 0n, temperature: null, stop: [], jsonSchema: "" };
}

// model is a model family or any alias a host lists it under, as
// abstraction.router/router@1 folds names. messages is 1..512. tools is 0..128.
// extensions holds vendor-prefixed keys <owner>/<name> with string values; a
// host ignores a key it does not know unless required_extensions names it, and
// then refuses unsupported_feature with reason extension:<key>. guarantees
// holds RequestGuarantee members. credential names an abstraction.credentials
// entry of the caller's account that a hosted host may spend under. The request
// carries no base URL, key, header or host name, and the encoded request fits
// one 1 MiB control frame.
export function newRequest() {
  return { model: "", messages: [], tools: [], options: null, extensions: {}, requiredExtensions: [], guarantees: [], credential: "" };
}

// Token counts the host reported: input, output, and cached input tokens
// counted within input. Zero where the host reported none.
export function newUsage() {
  return { input: 0n, output: 0n, cached: 0n };
}

// Spend the host reported for this reply, in millionths of currency, an ISO
// 4217 code or the host's own credit unit. Absent when the host reports no
// cost.
export function newCost() {
  return { micros: 0n, currency: "" };
}

// The result of one operation. completed carries the assistant message and
// stop_reason other than no_stop; every other outcome carries no_stop. refused
// means the host answered and refused the request (reason upstream:<status>).
// not_permitted carries reason rights:<word> for the complete decision on
// host:<name>, or credential:<outcome>:<name> for an applier refusal.
// budget_exceeded carries ceiling:<unit>:<credential>. unsupported_feature
// carries feature:<name> or extension:<key>. no_host carries router:<verdict>.
// cancelled carries cancel, idle or caller. unavailable carries
// rights:unavailable, credential:unavailable:<name> or upstream:<detail>; parts
// already delivered stay delivered. host and model name what served it, and are
// empty when nothing did. In the terminal delta message.parts is empty; the
// parts arrived in the deltas before it.
export function newReply() {
  return { outcome: "", reason: "", message: newMessage(), stopReason: "", usage: newUsage(), host: "", model: "", cost: null };
}

// sequence numbers an operation's deltas from 0 without gaps. chat operations
// use part, usage and end; transcription uses segment and transcription_end;
// speech uses audio chunks and speech_end; live uses transcript, audio and
// live_end; image uses image_progress, image_result and image_end. Text and
// audio bytes are bounded so every delta fits one service frame.
export function newDelta() {
  return { sequence: 0n, kind: "", index: 0n, part: null, usage: null, end: null, segment: null, transcriptionEnd: null, audio: null, speechEnd: null, transcript: null, liveEnd: null, imageProgress: null, imageResult: null, imageEnd: null };
}

// accepted carries an operation id of 1..128 bytes, the chosen host and model,
// and the provider's bounds: an ended operation stays observable for
// retention_ms; an operation with no Observe in flight or received for idle_ms
// is cancelled with reason idle, and its upstream request closed; the newest
// retained_deltas deltas stay readable. Every refusal carries the same reason
// words as Reply, an empty operation, host and model, and zero bounds.
// exhausted means the caller's concurrent operations are at the provider's
// bound.
export function newAdmission() {
  return { outcome: "", reason: "", operation: "", host: "", model: "", retentionMs: 0n, idleMs: 0n, retainedDeltas: 0n };
}

// page carries 0..max_deltas deltas from sequence cursor in order, within
// max_bytes of their compact JSON encoding except that a first delta larger
// than max_bytes is returned alone. next is the sequence after the last delta
// returned. at_end is true when the page holds the end delta or cursor is
// already past it. gap means cursor is older than the retained deltas: it
// carries no deltas and next set to the oldest retained sequence, from which a
// caller that accepts the loss continues. unknown means no operation of that id
// is visible to the caller: never started by it, retired after retention, or
// from an earlier provider epoch. Other refusals carry no deltas, next equal to
// cursor and at_end false.
export function newDeltaPage() {
  return { outcome: "", deltas: [], next: 0n, atEnd: false };
}

// cancelled means this call stopped the operation and closed its upstream
// request; the end delta reads cancelled with reason cancel. ended means the
// operation had already ended, and reply_outcome says how. Both carry
// reply_outcome; other outcomes carry none.
export function newCancellation() {
  return { outcome: "", replyOutcome: null };
}

// model is a model family or alias as in Request. inputs is 1..64 texts of
// 1..32768 bytes each. dimensions, when not zero, is 1..4096 and asks the host
// for vectors of that length; a reply of another length reads unavailable with
// reason upstream:dimensions. guarantees and credential select hosts and spend
// exactly as in Request. extensions holds vendor-prefixed keys <owner>/<name>
// with string values that a host ignores unless it knows them. The encoded
// request fits one 1 MiB control frame.
export function newEmbedRequest() {
  return { model: "", inputs: [], dimensions: 0n, guarantees: [], credential: "", extensions: {} };
}

// completed carries one vector per input, in input order, each the standard
// base64 of dimensions little-endian IEEE 754 float32 values, and dimensions of
// at least 1. The vectors of one reply hold at most 131072 values together; a
// larger upstream reply reads unavailable with reason upstream:too_large, and a
// caller embedding long vectors sends fewer inputs. usage.input is the input
// tokens the host counted. Every other outcome carries no vectors, zero
// dimensions, zero usage, and the reason words of Reply; unsupported_feature
// carries wire:<kind> for a host whose wire has no embeddings call. host and
// model name what served the call, and are empty when nothing did.
export function newEmbeddings() {
  return { outcome: "", reason: "", vectors: [], dimensions: 0n, usage: newUsage(), host: "", model: "", cost: null };
}

// A prerecorded transcription input. audio_digest is a canonical lowercase
// sha256 reference read through storage under the original caller's authority;
// bytes never cross this request. media_type is audio/wav, audio/mpeg,
// audio/mp4, audio/webm, audio/ogg or audio/flac. language is empty for
// detection or a 1..35 byte BCP-47-like tag. timestamps selects no units,
// segments, words or both; segment has no additional upstream latency and word
// may cost more. guarantees, credential and extensions have Request's meanings.
// The encoded request fits one 1 MiB control frame.
export function newTranscriptionRequest() {
  return { model: "", audioDigest: "", mediaType: "", language: "", timestamps: "", guarantees: [], credential: "", extensions: {} };
}

// One ordered transcript unit. index starts at zero separately for segment and
// word units. start_ms and end_ms are within the input duration, start_ms <=
// end_ms, and text is at most 32768 UTF-8 bytes so its delta fits a bounded
// page and service frame.
export function newTranscriptSegment() {
  return { index: 0n, kind: "", startMs: 0n, endMs: 0n, text: "" };
}

// The terminal result of one transcription operation. completed carries the
// detected or requested language and input duration in milliseconds. Other
// outcomes carry the common Reply outcome and reason words. unavailable reports
// malformed or inconsistent upstream results. host and model name what served
// the call, and are empty when nothing did.
export function newTranscriptionReply() {
  return { outcome: "", reason: "", language: "", durationMs: 0n, usage: newUsage(), host: "", model: "", cost: null };
}

// One text-to-speech request. voice is a backend voice name or id of 1..256
// safe URL-component bytes. text is 1..4096 Unicode scalar values and at most
// 16384 UTF-8 bytes. format is a codec the selected host explicitly supports.
// guarantees, credential and extensions have Request's meanings. No URL, path,
// key or header crosses this request.
export function newSpeechRequest() {
  return { model: "", voice: "", text: "", format: "", guarantees: [], credential: "", extensions: {} };
}

// One ordered speech output chunk. index starts at zero and data is 1..65536
// bytes. Concatenating chunks byte-for-byte yields the content named by
// SpeechReply.delivery.digest.
export function newAudioChunk() {
  return { index: 0n, data: new Uint8Array(0) };
}

// A typed result reference. Completed local work uses location local and a
// canonical sha256 digest readable through the caller's authorized content
// reader. Delegated work uses the remote trust domain as location; its digest
// is not claimed readable in the local store. Refusals carry empty strings and
// size zero.
export function newDelivery() {
  return { digest: "", mediaType: "", size: 0n, location: "" };
}

// The terminal result of one speech operation. completed carries the exact
// concatenated audio as a typed delivery and the Unicode scalar count charged.
// Other outcomes carry an empty delivery. host and model name what served the
// call.
export function newSpeechReply() {
  return { outcome: "", reason: "", delivery: newDelivery(), characters: 0n, usage: newUsage(), host: "", model: "", cost: null };
}

// One live audio response session. pcm16_24000 is mono signed 16-bit
// little-endian PCM at 24000 Hz for input and output. Voice is 1..256 safe
// URL-component bytes. Guarantees and credential have Request meanings. Start
// creates one session; Commit finishes its input and requests one final model
// response.
export function newLiveRequest() {
  return { model: "", voice: "", format: "", guarantees: [], credential: "", extensions: {} };
}

// next_sequence is the next Append sequence expected, starting at zero. A retry
// of the most recently acknowledged identical frame is duplicate and sends
// nothing upstream. Other repeated or skipped sequences are out_of_order. After
// Commit no Append is accepted. An uncertain upstream write ends the session as
// unavailable; the service never retries it.
export function newLiveInputResult() {
  return { outcome: "", nextSequence: 0n };
}

// One bounded output transcript fragment, at most 16384 UTF-8 bytes. Fragments
// append in delta order. A final marker may have empty text. It marks
// transcript completion, not session completion.
export function newLiveTranscript() {
  return { text: "", isFinal: false };
}

// Final live-session outcome. Completed output audio is committed through the
// original caller's authorized content writer; delivery names those exact
// bytes. Failed sessions carry empty delivery. Input and output byte counts
// describe PCM processed, and usage carries upstream token counts.
export function newLiveReply() {
  return { outcome: "", reason: "", delivery: newDelivery(), usage: newUsage(), inputAudioBytes: 0n, outputAudioBytes: 0n, host: "", model: "" };
}

// One image generation or edit request. prompt is 1..32768 UTF-8 bytes. size is
// auto or WIDTHxHEIGHT with positive decimal dimensions. count is 1..10.
// Generate carries no input digests. Edit carries one canonical image SHA-256
// digest and media type and may carry one canonical mask digest and media type.
// Input media types are PNG, JPEG or WebP; masks are PNG. Digests are
// authorized and resolved only by the selected runtime. extensions holds
// declared vendor workflow or template controls; a named required extension
// absent from the selected adapter is refused before paid work. No URL, file
// path, key, header, inline image or workflow crosses this request.
export function newImageRequest() {
  return { model: "", mode: "", prompt: "", size: "", count: 0n, imageDigest: "", imageMediaType: "", maskDigest: "", maskMediaType: "", guarantees: [], credential: "", requiredExtensions: [], extensions: {} };
}

// One bounded progress update. percent, when nonzero, is 1..100; zero means the
// backend reported no numeric progress. message is at most 4096 UTF-8 bytes and
// contains no submitted content or credential material.
export function newImageProgress() {
  return { percent: 0n, message: "" };
}

// One completed image in request order. index is 0..count-1. delivery
// identifies an authorized PNG, JPEG or WebP result and the runtime that owns
// it.
export function newImageResult() {
  return { index: 0n, delivery: newDelivery() };
}

// The terminal result of one image operation. Completed carries exactly count
// ordered deliveries equal to the streamed image_result deltas and images is
// the charged output count. Other outcomes carry no deliveries. host and model
// name what served the call.
export function newImageReply() {
  return { outcome: "", reason: "", deliveries: [], images: 0n, usage: newUsage(), host: "", model: "", cost: null };
}

// A credential's daily limits per UTC day: tokens (input plus output), spend in
// currency millionths, requests, images, audio seconds and characters. Zero or
// absent means no limit in that unit. The provider enforces every configured
// unit at admission and records the applicable units when each profile ends.
export function newCeilingLimit() {
  return { tokensPerDay: 0n, microsPerDay: 0n, requestsPerDay: 0n, imagesPerDay: 0n, audioSecondsPerDay: 0n, charactersPerDay: 0n };
}

// One host the runtime reaches. A remote runtime is an
// abstraction.facade/registry@1 declaration; router@1 Hosts lists its hosts as
// <name>/<host>. profiles holds 1..16 distinct host_profiles members or
// <owner>/<name>@<n>; empty in AddHost selects the wire's default:
// openai-compatible and every local kind serve chat, embed, transcription,
// speech and image, and anthropic-messages and any other wire serve chat.
// declared_by is asserted by the runtime, operator for a host added through
// AddHost, and AddHost refuses a non-empty value as invalid. name is 1..64
// bytes of a-z 0-9 _ - and unique. A local host (hosted false) names a
// local_host_kinds member as both name and kind, and the base URL of that
// runtime on this machine, and carries no credential or ceiling. A hosted host
// names a wire kind (router wire_kinds or <owner>/<name>@<n>), its https or
// loopback http API root, the abstraction.credentials name the service applies
// to it, and optionally that credential's ceiling. base carries no user
// information, query or fragment.
export function newHostEntry() {
  return { name: "", hosted: false, kind: "", base: "", credential: "", ceiling: null, profiles: [], declaredBy: "" };
}

// What a credential has spent on UTC day (YYYY-MM-DD), counted from provider
// replies: tokens, currency millionths, requests, generated images, whole audio
// seconds and characters.
export function newSpend() {
  return { day: "", tokens: 0n, micros: 0n, requests: 0n, audioSeconds: 0n, characters: 0n, images: 0n };
}

// A configured host and the router's latest reading of it: up, or why not.
// spend is present for a hosted host that names a credential.
export function newHostState() {
  return { entry: newHostEntry(), up: false, why: "", spend: null };
}

// page carries every configured host, at most 64, and the configuration
// revision AddHost and RemoveHost take. invalid is reserved for a request this
// provider cannot interpret. Refusals carry an empty revision and no hosts.
export function newHostList() {
  return { outcome: "", revision: "", hosts: [] };
}

// applied carries the new configuration revision; the runtime reads the hosts
// again at once. conflict means expected_revision is not current, or AddHost
// named an existing host, and carries the current revision. unknown means
// RemoveHost named no host. invalid carries the field in reason. Other outcomes
// carry an empty revision. no_secure_store is not used by host edits.
export function newHostChange() {
  return { outcome: "", revision: "", reason: "" };
}

// A local key minted for one program. program is the normalized absolute
// executable path the window requires of the bound peer presenting the key.
// name is the abstraction.credentials record holding it as kind
// openabstractions/local-key@1. credential, when present, is the hosted
// credential name the window's requests may spend under; without it the
// window's requests are local-only. issued_unix_ms is when it was minted, in
// milliseconds since the Unix epoch. issued_by is the operator program that
// issued it. lost means the platform store no longer holds the key. Metadata
// only; no field derives from the key.
export function newLocalKey() {
  return { program: "", name: "", credential: "", issuedUnixMs: 0n, issuedBy: "", state: "" };
}

// page carries every retained local key of the receiving account, at most 256,
// revoked ones included. Refusals carry no keys.
export function newKeyList() {
  return { outcome: "", keys: [] };
}

// applied carries the key, once, and its record. The key is the only secret
// operator@1 ever returns: the runtime minted it, it authorizes nothing by
// itself, and no later call reads it back. The operator gives it to the
// program, for example as that program's API key setting. conflict means the
// program holds an active key; revoke it first. invalid carries the field in
// reason. no_secure_store means the runtime has no platform store to hold it.
// Other outcomes carry no key and no record.
export function newKeyIssued() {
  return { outcome: "", reason: "", key: "", record: null };
}

// applied destroys the key in the platform store; the window refuses it from
// the next request. unknown means the program holds no active key.
export function newKeyRevoked() {
  return { outcome: "" };
}

// profile is the host profile of the call; empty is chat. audio_seconds is the
// rounded-up input duration counted for transcription, characters is text sent
// for speech, and images is the generated image count. domain names the other
// trust domain of a decision: on the delegating runtime the remote host it went
// to, and on the remote runtime the caller its client certificate maps to.
// claim, on the remote runtime, is the program the delegating runtime says
// asked, attributed to domain; it decides nothing. route remote is a call that
// arrived over the remote transport, whose rung names that transport. One
// decision in journal order, at unix_ms milliseconds since the Unix epoch: an
// ended operation, an admission refusal, or a window refusal before admission.
// Entries carry names and counts, never headers, credentials or content.
export function newAuditEntry() {
  return { sequence: 0n, unixMs: 0n, route: "", rung: "", program: "", operation: "", host: "", model: "", credential: "", outcome: "", reason: "", tokensIn: 0n, tokensOut: 0n, wallMs: 0n, ceiling: "", domain: "", claim: "", profile: "", audioSeconds: 0n, characters: 0n, images: 0n };
}

// page carries at most max_entries entries from sequence cursor in order. The
// runtime retains its newest entries across restarts; a cursor older than the
// oldest retained entry reads gap with next at the oldest retained sequence and
// no entries. at_end is true when no entry after the page exists yet. Other
// refusals carry no entries, next equal to cursor and at_end false.
export function newAuditPage() {
  return { outcome: "", entries: [], next: 0n, atEnd: false };
}

// page carries the gateway window setting kept in the runtime state at
// revision, and the window in this runtime now. open and address are the
// setting; it is off by default and address is empty until one is set.
// listening is true when the window accepts connections at listening_address. A
// window opened for this process by serve runtime --gateway reads listening
// with the setting unchanged. why names the failure when open is set and the
// window is not listening, as listen:<detail>. Refusals carry an empty
// revision, addresses and why, and open and listening false.
export function newGatewayState() {
  return { outcome: "", revision: "", open: false, address: "", listening: false, listeningAddress: "", why: "" };
}

// applied carries the new setting revision; the runtime has opened or closed
// the window before replying. conflict means expected_revision is not current
// and carries the current revision. invalid carries the field in reason:
// address when it is not 127.0.0.1:<port>. unavailable carries listen:<detail>
// in reason when the setting was written and the window could not listen. Other
// outcomes carry an empty revision.
export function newGatewayChange() {
  return { outcome: "", revision: "", reason: "" };
}

